 async function renderPlate({fit=true}={}){prepare();ToolpathUI.close();$('#sliceResult').dataset.signature='';$('#sliceResult').innerHTML='<div class="slice-result-empty">'+(selectedTask?I18n.t('正在读取本盘切片结果…'):I18n.t('本盘尚未切片；每盘分别选择设备与料卷。'))+'</div>';syncAll();paintCopies();paintLists();paintPlates();paintButtons();viewer?.set(options(),activeCopy,selectedIndices());$('#sliceSceneEmpty').hidden=!!selected;$('#sliceModelName').textContent=selected?I18n.t('正在读取模型…'):I18n.t('空打印板');if(!selected){viewer?.loadModels([]);message(I18n.t('空打印板 · 导入 STL 或从其他盘移入对象。'));return}const board=plates[activePlate].id,taskID=selectedTask;await loadModel(selected,{fit});if(!taskID||plates[activePlate]?.id!==board)return;let task=workspace.tasks.find(t=>t.id===taskID);if(!task){try{const r=await Remote.request('/api/slicing/task?id='+taskID);if(plates[activePlate]?.id!==board||selectedTask!==taskID)return;task=r.task;workspace.tasks.push(task)}catch(e){if(plates[activePlate]?.id===board)message(I18n.t('本盘结果读取失败：')+I18n.system(e.message),true);return}}if(plates[activePlate]?.id===board&&selectedTask===taskID){showTask(task);preview()}}
 function switchPlate(index){if(!plates[index]||index===activePlate)return;viewer?.finish();capturePlate();activePlate=index;activatePlate();editHistory.select(snapshot());storage?.changed();void renderPlate()}
 function paintPlates(){const list=$('#slicePlates');if(!list)return;const sig=JSON.stringify([activePlate,plates.map((p,i)=>[p.id,p.name,i===activePlate?placements.length:p.options.copies?.length||0,p.taskId,workspace.tasks.find(t=>t.id===p.taskId)?.state])]);if(list.dataset.signature!==sig){const focus=document.activeElement?.closest('[data-plate]')?.dataset.plate;list.dataset.signature=sig;list.innerHTML=plates.map((p,i)=>{const n=i===activePlate?placements.length:p.options.copies?.length||0,t=workspace.tasks.find(t=>t.id===p.taskId),state=t?.state||'unprepared';return I18n.html`<button type="button" role="tab" aria-selected="${i===activePlate}" tabindex="${i===activePlate?0:-1}" data-plate="${i}" title="${esc(p.name)} · ${n} 个对象${t?' · '+labels[t.state]:''}"><span class="plate-status ${state}"></span><strong>${esc(p.name)}</strong><small>${n}</small></button>`}).join('');$$('[data-plate]',list).forEach(b=>{b.onclick=()=>switchPlate(Number(b.dataset.plate));b.onkeydown=e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();switchPlate((activePlate+(e.key==='ArrowRight'?1:plates.length-1))%plates.length);$('[data-plate="'+activePlate+'"]',list)?.focus()}}});if(focus!==undefined)$('[data-plate="'+focus+'"]',list)?.focus({preventScroll:true});if(list.dataset.active!==String(activePlate)){const item=$('[data-plate="'+activePlate+'"]',list),a=item?.getBoundingClientRect(),b=list.getBoundingClientRect();if(a){if(a.right>b.right)list.scrollLeft+=a.right-b.right;if(a.left<b.left)list.scrollLeft-=b.left-a.left}list.dataset.active=String(activePlate)}}$('#slicePlateAdd').disabled=plates.length>=8||busy;$('#slicePlateMove').disabled=!selected||!placements.length||busy;$('#slicePlateDelete').disabled=plates.length<2||busy;$('#slicePlateRename').disabled=busy;const tag=$('.studio-plate-tag');if(tag)tag.textContent=plates[activePlate]?.name||I18n.t('打印板');$('#slicePlateCount').textContent=plates.length+I18n.t(' / 8 盘')}
 function plateEditDone(text,{fit=true}={}){selectedTask=plates[activePlate].taskId||0;editHistory.record(snapshot());paintHistory();storage?.changed();void renderPlate({fit});message(text)}
