 function deletePlate(){if(plates.length<2)return;viewer?.finish();capturePlate();const index=activePlate,p=plates[index];if(!plates.some((b,i)=>i!==index&&b.modelId)){message(I18n.t('工程至少保留一个模型，请先将对象移到其他盘。'),true);return}const remove=()=>{plates.splice(index,1);activePlate=Math.min(index,plates.length-1);activatePlate();plateEditDone(I18n.t('打印板已移除；可以撤销。源模型与历史切片保留。'))};if(p.modelId)confirmAction(I18n.t('移除这块打印板'),I18n.msg`移除“${esc(p.name)}”及其摆放。源模型和历史切片保留，可用撤销恢复。`,remove);else remove()}
 function movePlateObject(){if(!canEditSelection())return;viewer?.finish();capturePlate();const origin=plates[activePlate].id,indices=selectedIndices(),signature=JSON.stringify([placements,indices]),host=root,uid=owner;modal(I18n.t('移动 ')+indices.length+I18n.t(' 个对象到另一盘'),I18n.html`<form id="plateMoveForm"><p class="form-help">移动选中的 ${indices.length} 个对象，目标盘会重新自动排版。继承项跟随目标盘，单独设置保持；移动后，两盘需要重新切片。</p><label>目标打印板<select class="input" name="target">${plates.map((p,i)=>i===activePlate?'':I18n.html`<option value="${i}">${esc(p.name)} · ${p.options.copies?.length||0} 个对象</option>`).join('')}${plates.length<8?I18n.html('<option value="new">新建打印板</option>'):''}</select></label><p class="form-error" role="alert"></p><button class="button primary" type="submit">移动 ${indices.length} 个对象</button></form>`,I18n.html`<button class="button" data-cancel>取消</button>`);const form=$('#plateMoveForm');form.onsubmit=e=>{e.preventDefault();try{if(root!==host||owner!==uid||!host.isConnected||!form.isConnected||!$('#modal').open)return;if(!canEditSelection()||plates[activePlate].id!==origin||signature!==JSON.stringify([placements,selectedIndices()]))throw Error(I18n.t('打印板或选中对象已变化，请重新选择'));const next=SlicerPlates.clone(plates),value=form.elements.target.value,target=value==='new'?next.length:Number(value);if(value==='new'){if(next.length>=8)throw Error(I18n.t('工程最多 8 盘'));const names=new Set(next.map(p=>p.name));let n=1;while(names.has(I18n.t('打印板 ')+String(n).padStart(2,'0')))n++;next.push(SlicerPlates.make(I18n.t('打印板 ')+String(n).padStart(2,'0'),draft))}plates=SlicerPlates.moveMany(next,activePlate,target,indices,workspace.models);activePlate=target;activatePlate();$('#modal').close();plateEditDone(I18n.t('已移动 ')+indices.length+I18n.t(' 个对象并自动排版；可一次撤销。'),{fit:false})}catch(error){form.querySelector('[role=alert]').textContent=I18n.system(error.message)+I18n.t(' 原布局已保留。')}}}
 function mountPlates(){ensurePlate();const bar=document.createElement('div');bar.className='studio-plates';bar.innerHTML=I18n.html('<div id="slicePlates" class="studio-plate-tabs" role="tablist" aria-label="工程打印板"></div><button type="button" id="slicePlateAdd" class="studio-plate-add" aria-label="新增打印板" title="新增打印板">＋</button><span id="slicePlateCount"></span><details class="studio-plate-menu"><summary aria-label="打印板操作">···</summary><div><button type="button" id="slicePlateMove">移动选中对象到…</button><button type="button" id="slicePlateRename">重命名本盘</button><button type="button" id="slicePlateDelete">移除本盘</button><small>每盘独立切片、确认设备与料卷</small></div></details>');$('.studio-body').before(bar);for(const b of bar.querySelectorAll('button'))if(!b.hasAttribute('aria-label'))b.setAttribute('aria-label',b.textContent);$('#slicePlateAdd').onclick=addPlate;$('#slicePlateMove').onclick=movePlateObject;$('#slicePlateRename').onclick=renamePlate;$('#slicePlateDelete').onclick=deletePlate;bar.querySelector('details').addEventListener('click',e=>{if(e.target.closest('button'))bar.querySelector('details').open=false});paintPlates()}
 function options(){const {modelId:ignored,...settings}=draft;return {...settings,rotation:[...draft.rotation],copies:placements.map(SlicerCopies.clone)}}
 function savePlacement(){if(placements.length)placements[activeCopy]={...SlicerCopies.clone(placements[activeCopy]),...SlicerCopies.transform(draft)}}
 function pickCopy(index,event={}){faceUI?.cancel();if(!placements[index]||busy||gestureActive)return;viewer?.finish();selectedCopies=SlicerSelection.pick(selectedIndices(),index,{ctrlKey:event.ctrlKey||selectionMode,metaKey:event.metaKey,shiftKey:event.shiftKey},placements.length,selectionAnchor);if(!event.shiftKey)selectionAnchor=index;activeCopy=selectedCopies.includes(index)?index:selectedCopies[selectedCopies.length-1];Object.assign(draft,SlicerCopies.transform(placements[activeCopy]));editHistory.select(snapshot());storage?.changed();syncFields();paintCopies();viewer?.set(options(),activeCopy,selectedIndices())}
 function pickMany(indices,{additive=false}={}){faceUI?.cancel();if(!canEditSelection())return;const valid=indices.filter(i=>Number.isInteger(i)&&placements[i]);if(!valid.length){message(I18n.t('选框内没有完整模型，原选择保持。'));return}selectedCopies=[...new Set([...(additive?selectedIndices():[]),...valid])].sort((a,b)=>a-b);if(!selectedCopies.includes(activeCopy))activeCopy=selectedCopies[0];selectionAnchor=activeCopy;Object.assign(draft,SlicerCopies.transform(placements[activeCopy]));editHistory.select(snapshot());storage?.changed();syncFields();paintCopies();viewer?.set(options(),activeCopy,selectedIndices());message(I18n.t('已框选 ')+selectedIndices().length+I18n.t(' 个模型，可切换“移动”整组平移。'))}
 function paintTools(){const multi=selectedIndices().length>1,locked=!canEditSelection();for(const el of $$('[data-place],[data-rotate]'))el.disabled=multi||locked;for(const id of ['sliceApplyCount','sliceCopyCount','sliceCenter','sliceReset','sliceGround'])if($('#'+id))$('#'+id).disabled=multi||locked;for(const b of $$('[data-quarter]'))b.disabled=locked;for(const id of ['sliceSelectAll','sliceSelectOnly','sliceMultiToggle'])if($('#'+id))$('#'+id).disabled=locked;const modeButton=$('#sliceMultiToggle');if(modeButton){modeButton.setAttribute('aria-pressed',String(selectionMode));modeButton.classList.toggle('active',selectionMode)}const scope=$('#sliceRotateScope');if(scope)scope.textContent=multi?I18n.t('分别旋转选中的 ')+selectedIndices().length+I18n.t(' 个模型'):I18n.t('旋转选中模型');objectUI?.sync();faceUI?.sync();sizeUI?.sync();if(multi){for(const el of $$('[data-place],[data-rotate]')){el.value='';el.placeholder=I18n.t('单选后编辑')}const label=$('#sliceScaleSummary');if(label)label.textContent=I18n.t('已选 ')+selectedIndices().length+I18n.t(' 个对象 · 各自尺寸保持，单选后调整')}batchUI?.sync();for(const b of $$('[data-transform]')){const active=b.dataset.transform===toolMode;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));b.disabled=locked||(multi&&b.dataset.transform==='rotate')}const hint=$('#sliceToolHint');if(hint)hint.textContent=studio?.mode==='preview'?I18n.t('只读预览 · 拖动旋转视角'):{select:I18n.t('点击选择 · 拖动空白旋转视角'),box:I18n.t('完整框住模型 · Ctrl/Shift 追加 · 右键平移视角'),translate:multi?I18n.t('整组平移 · 保持相对位置 · 自动贴底'):I18n.t('拖动 X / Y 手柄移动 · 自动贴底'),rotate:I18n.t('拖动圆环旋转 · 自动贴底'),face:I18n.t('点击外侧平面预览 · 右键旋转 · Esc 取消'),scale:I18n.t('拖动手柄等比缩放 · 范围 0.01–10')}[toolMode]}
 function setTool(mode){faceUI?.cancel();if(!['select','box','translate','rotate'].includes(mode)||selectedIndices().length>1&&mode==='rotate')return;viewer?.finish();toolMode=mode;viewer?.tool(mode);paintTools()}
 function paintIssues(){const node=$('#sliceIssues');if(!node)return;const issues=bounds?.issues||[];node.hidden=!issues.length;const signature=JSON.stringify(issues);if(node.dataset.signature!==signature){node.dataset.signature=signature;node.innerHTML=issues.map(item=>I18n.html`<button type="button" data-issue="${item.index}"><strong>对象 ${item.index+1}</strong><span>${esc(item.reasons.map(r=>r.text).join('；'))}</span></button>`).join('');$$('[data-issue]',node).forEach(b=>b.onclick=()=>{pickCopy(Number(b.dataset.issue));viewer?.view('selected')})}for(const b of $$('[data-copy]')){const issue=issues.find(item=>item.index===Number(b.dataset.copy));b.classList.toggle('has-issue',!!issue);b.setAttribute('aria-label',b.textContent+(issue?' · '+issue.reasons.map(r=>r.text).join('；'):''))}}
 function applyTransform(patch){if(!root?.isConnected||owner!==data.user?.id||!placements.length||busy||modelLoading||modelFailed)return;if(selectedIndices().length>1){if(toolMode!=='translate'||![patch.x,patch.y].every(Number.isFinite))return;try{placements=SlicerSelection.translate(placements,selectedIndices(),patch.x,patch.y);Object.assign(draft,SlicerCopies.transform(placements[activeCopy]));changed('gizmo')}catch(e){message(I18n.system(e.message),true)}return}for(const key of ['x','y','scale'])if(Number.isFinite(patch[key]))draft[key]=patch[key];if(Array.isArray(patch.rotation)&&patch.rotation.length===3&&patch.rotation.every(Number.isFinite))draft.rotation=[...patch.rotation];syncFields();changed('gizmo')}
 function paintCopies(){const list=$('#sliceCopies');if(!list)return;list.innerHTML=placements.map((p,i)=>`<button type="button" class="${selectedIndices().includes(i)?'active':''}" aria-pressed="${selectedIndices().includes(i)}" data-copy="${i}" title="${esc(workspace.models.find(m=>m.id===p.modelId)?.filename||I18n.t('对象'))}">${i+1} · ${esc((workspace.models.find(m=>m.id===p.modelId)?.filename||I18n.t('对象')).replace(/\.stl$/i,''))}</button>`).join('');$$('[data-copy]').forEach(b=>b.onclick=e=>pickCopy(Number(b.dataset.copy),e));for(const b of $$('[data-copy]')){const p=placements[Number(b.dataset.copy)];if(p.process&&Object.keys(p.process).length){const tag=document.createElement('span');tag.className='slice-copy-process-tag';tag.textContent=I18n.t('单独工艺');b.append(tag)}}const scope=$('#sliceSelectionScope');if(scope)scope.textContent=I18n.t('已选 ')+selectedIndices().length+' / '+placements.length+I18n.t(' 个对象');if(selectedIndices().length>1&&toolMode==='rotate'){toolMode='select';viewer?.tool('select')}const id=placements[activeCopy]?.modelId;$('#sliceCopyCount').value=placements.filter(p=>p.modelId===id).length||1;$('#sliceCopyLabel').textContent=placements.length?(selectedIndices().length>1?I18n.t('已选 ')+selectedIndices().length+I18n.t(' 个'):I18n.t('选中对象 ')+(activeCopy+1))+I18n.t(' · 整盘 ')+placements.length+I18n.t(' 个'):I18n.t('先加入模型');$('#sliceDuplicate').textContent=selectedIndices().length>1?I18n.t('复制 ')+selectedIndices().length+I18n.t(' 个'):I18n.t('复制');$('#sliceRemoveCopy').textContent=selectedIndices().length>1?I18n.t('删除 ')+selectedIndices().length+I18n.t(' 个'):I18n.t('删除');for(const id of ['sliceDuplicate','sliceRemoveCopy','sliceArrange','sliceApplyCount','sliceCenter'])$('#'+id).disabled=!selected||!placements.length;paintTools();paintIssues()}
 function arrangeCopies(next){let triangles=0;for(const p of next){const m=workspace.models.find(m=>m.id===p.modelId);if(!m)throw Error(I18n.t('盘内源模型不存在，请重新读取工程'));triangles+=m.triangles}if(next.length>64||triangles>150000)throw Error(I18n.t('整盘最多 64 个对象、合计 150,000 个三角面'));return SlicerCopies.arrange(next,p=>workspace.models.find(m=>m.id===p.modelId).bounds.size,draft)}
 function resizeCopies(count){if(SlicerPlates.count(projectState()?.plates||[])-placements.filter(p=>p.modelId===placements[activeCopy]?.modelId).length+count>256)throw Error(I18n.t('一个工程最多 256 个对象'));if(!Number.isInteger(count)||count<1||count>64)throw Error(I18n.t('选中模型数量须为 1–64'));const id=placements[activeCopy]?.modelId;if(!id)return;let next=placements.map(SlicerCopies.clone),n=next.filter(p=>p.modelId===id).length;while(n<count){next.push(SlicerCopies.duplicate(placements[activeCopy]));n++}for(let i=next.length-1;n>count&&i>=0;i--)if(next[i].modelId===id){next.splice(i,1);n--}next=arrangeCopies(next);placements=next;activeCopy=next.findIndex(p=>p.modelId===id);singleSelection();Object.assign(draft,SlicerCopies.transform(placements[activeCopy]));syncFields();paintCopies();changed();loadModel(selected)}
