 function restoreTask(t,confirmed=false){if(storage&&!confirmed){storage.guard(()=>restoreTask(t,true));return}prepare();selected=t.modelId;selectedTask=0;draft={...t.options,rotation:[...t.options.rotation]};placements=(t.options.copies?.length?t.options.copies:[t.options]).map(p=>({...SlicerCopies.clone(p),instanceId:p.instanceId||crypto.randomUUID(),modelId:p.modelId||t.modelId}));activeCopy=0;singleSelection();Object.assign(draft,SlicerCopies.transform(placements[0]));paintCopies();syncAll();paintLists();loadModel(selected);changed('',false);capturePlate();resetHistory();storage?.changed()}
